window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3875df6edc21c257"]={"versions": [{"id": "FIG-3875df6edc21c257", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm für den Teilschritt „Verify inputs of the protect function“ innerhalb der Funktion <code>E2E_P06Protect()</code> des AUTOSAR E2E-Profils 6 (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Kontrollflusslogik zur Eingangsparameterprüfung vor der Berechnung der E2E-Headerdaten und Prüfsummen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm bindet als Kontext die Funktion <code>E2E_P06Protect()</code> ein. Geprüft werden die Eingabeparameter:</p>\n<ul class=\"fig-list\">\n<li><code>Config</code>: Zeiger auf die Konfigurationsstruktur (<code>E2E_P06ConfigType</code>) mit den Elementen <code>MinDataLength</code> und <code>MaxDataLength</code> (jeweils in Bit).</li>\n<li><code>State</code>: Zeiger auf die Zustandsstruktur (<code>E2E_P06ProtectStateType</code>).</li>\n<li><code>Data</code>: Zeiger auf das Daten-Array (<code>uint8*</code>).</li>\n<li><code>Length</code>: Länge der übergebenen Nutzdaten in Byte.</li>\n</ul>\n<p class=\"fig-p\">Als Kontrollknoten treten ein Initialknoten (Startknoten), zwei Verzweigungsknoten (Decisions) und drei finale Aktivitätsendknoten auf, die mit den Kontrollzuständen <code>no input</code>, <code>input ok</code> und <code>wrong input</code> beschriftet sind.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss startet am Initialknoten und führt zur ersten Verzweigung.</li>\n<li>An der ersten Verzweigung wird die Pointer-Gültigkeit über den Guard <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code> evaluiert:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Evaluierung zu <code>[FALSE]</code>: Der Kontrollfluss zweigt nach links ab und terminiert im Endknoten <code>no input</code> (Rückgabewert <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Evaluierung zu <code>[TRUE]</code>: Der Kontrollfluss geht weiter zur zweiten Verzweigung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>An der zweiten Verzweigung wird die Datenlänge gegen die konfigurierten Bitlängen über den Guard <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code> geprüft:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Evaluierung zu <code>[FALSE]</code>: Der Kontrollfluss zweigt nach rechts ab und terminiert im Endknoten <code>wrong input</code> (Rückgabewert <code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Evaluierung zu <code>[TRUE]</code>: Der Kontrollfluss führt direkt vertikal in den Endknoten <code>input ok</code>, womit die Eingangsprüfung erfolgreich abgeschlossen ist und die Ausführung von <code>E2E_P06Protect()</code> fortgesetzt werden darf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00424]</code> ist das in der Abbildung spezifizierte Verhalten normativ verpflichtend für Implementierungen von <code>E2E_P06Protect()</code>.</p>\n<p class=\"fig-p\">Entwickler-Hinweise:</p>\n<ul class=\"fig-list\">\n<li>Beide Bedingungen müssen in exakt dieser Reihenfolge geprüft werden; die Nullzeigerprüfung guardet den dereferenzierenden Zugriff auf <code>Config-&gt;MinDataLength</code> bzw. <code>Config-&gt;MaxDataLength</code>.</li>\n<li>Die Konfigurationsgrenzen <code>MinDataLength</code> und <code>MaxDataLength</code> sind in Bits definiert, weshalb der Vergleich mit <code>Length</code> (in Bytes) durch Division durch 8 (<code>/ 8</code>) normiert werden muss.</li>\n<li>Das Ergebnis <code>no input</code> korrespondiert mit dem Fehlercode <code>E2E_E_INPUTERR_NULL</code>, <code>wrong input</code> mit <code>E2E_E_INPUTERR_WRONG</code> und <code>input ok</code> mit dem regulären Fortsetzen der Schutzfunktionslogik.</li>\n</ul>"}, {"id": "FIG-3e360a8db9d01f02", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm für den Teilschritt „Verify inputs of the protect function“ innerhalb der Funktion <code>E2E_P06Protect()</code> des AUTOSAR E2E-Profils 6 (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Kontrollflusslogik zur Eingangsparameterprüfung vor der Berechnung der E2E-Headerdaten und Prüfsummen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm bindet als Kontext die Funktion <code>E2E_P06Protect()</code> ein. Geprüft werden die Eingabeparameter:</p>\n<ul class=\"fig-list\">\n<li><code>Config</code>: Zeiger auf die Konfigurationsstruktur (<code>E2E_P06ConfigType</code>) mit den Elementen <code>MinDataLength</code> und <code>MaxDataLength</code> (jeweils in Bit).</li>\n<li><code>State</code>: Zeiger auf die Zustandsstruktur (<code>E2E_P06ProtectStateType</code>).</li>\n<li><code>Data</code>: Zeiger auf das Daten-Array (<code>uint8*</code>).</li>\n<li><code>Length</code>: Länge der übergebenen Nutzdaten in Byte.</li>\n</ul>\n<p class=\"fig-p\">Als Kontrollknoten treten ein Initialknoten (Startknoten), zwei Verzweigungsknoten (Decisions) und drei finale Aktivitätsendknoten auf, die mit den Kontrollzuständen <code>no input</code>, <code>input ok</code> und <code>wrong input</code> beschriftet sind.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss startet am Initialknoten und führt zur ersten Verzweigung.</li>\n<li>An der ersten Verzweigung wird die Pointer-Gültigkeit über den Guard <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code> evaluiert:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Evaluierung zu <code>[FALSE]</code>: Der Kontrollfluss zweigt nach links ab und terminiert im Endknoten <code>no input</code> (Rückgabewert <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Evaluierung zu <code>[TRUE]</code>: Der Kontrollfluss geht weiter zur zweiten Verzweigung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>An der zweiten Verzweigung wird die Datenlänge gegen die konfigurierten Bitlängen über den Guard <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code> geprüft:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Evaluierung zu <code>[FALSE]</code>: Der Kontrollfluss zweigt nach rechts ab und terminiert im Endknoten <code>wrong input</code> (Rückgabewert <code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Evaluierung zu <code>[TRUE]</code>: Der Kontrollfluss führt direkt vertikal in den Endknoten <code>input ok</code>, womit die Eingangsprüfung erfolgreich abgeschlossen ist und die Ausführung von <code>E2E_P06Protect()</code> fortgesetzt werden darf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00424]</code> ist das in der Abbildung spezifizierte Verhalten normativ verpflichtend für Implementierungen von <code>E2E_P06Protect()</code>.</p>\n<p class=\"fig-p\">Entwickler-Hinweise:</p>\n<ul class=\"fig-list\">\n<li>Beide Bedingungen müssen in exakt dieser Reihenfolge geprüft werden; die Nullzeigerprüfung guardet den dereferenzierenden Zugriff auf <code>Config-&gt;MinDataLength</code> bzw. <code>Config-&gt;MaxDataLength</code>.</li>\n<li>Die Konfigurationsgrenzen <code>MinDataLength</code> und <code>MaxDataLength</code> sind in Bits definiert, weshalb der Vergleich mit <code>Length</code> (in Bytes) durch Division durch 8 (<code>/ 8</code>) normiert werden muss.</li>\n<li>Das Ergebnis <code>no input</code> korrespondiert mit dem Fehlercode <code>E2E_E_INPUTERR_NULL</code>, <code>wrong input</code> mit <code>E2E_E_INPUTERR_WRONG</code> und <code>input ok</code> mit dem regulären Fortsetzen der Schutzfunktionslogik.</li>\n</ul>"}, {"id": "FIG-6a4321c1015804e9", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm für den Teilschritt „Verify inputs of the protect function“ innerhalb der Funktion <code>E2E_P06Protect()</code> des AUTOSAR E2E-Profils 6 (AUTOSAR PRS E2EProtocol). Das Diagramm spezifiziert die Kontrollflusslogik zur Eingangsparameterprüfung vor der Berechnung der E2E-Headerdaten und Prüfsummen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm bindet als Kontext die Funktion <code>E2E_P06Protect()</code> ein. Geprüft werden die Eingabeparameter:</p>\n<ul class=\"fig-list\">\n<li><code>Config</code>: Zeiger auf die Konfigurationsstruktur (<code>E2E_P06ConfigType</code>) mit den Elementen <code>MinDataLength</code> und <code>MaxDataLength</code> (jeweils in Bit).</li>\n<li><code>State</code>: Zeiger auf die Zustandsstruktur (<code>E2E_P06ProtectStateType</code>).</li>\n<li><code>Data</code>: Zeiger auf das Daten-Array (<code>uint8*</code>).</li>\n<li><code>Length</code>: Länge der übergebenen Nutzdaten in Byte.</li>\n</ul>\n<p class=\"fig-p\">Als Kontrollknoten treten ein Initialknoten (Startknoten), zwei Verzweigungsknoten (Decisions) und drei finale Aktivitätsendknoten auf, die mit den Kontrollzuständen <code>no input</code>, <code>input ok</code> und <code>wrong input</code> beschriftet sind.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss startet am Initialknoten und führt zur ersten Verzweigung.</li>\n<li>An der ersten Verzweigung wird die Pointer-Gültigkeit über den Guard <code>(Config != NULL) &amp;&amp; (State != NULL) &amp;&amp; (Data != NULL)</code> evaluiert:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Evaluierung zu <code>[FALSE]</code>: Der Kontrollfluss zweigt nach links ab und terminiert im Endknoten <code>no input</code> (Rückgabewert <code>E2E_E_INPUTERR_NULL</code>).</li>\n<li>Evaluierung zu <code>[TRUE]</code>: Der Kontrollfluss geht weiter zur zweiten Verzweigung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>An der zweiten Verzweigung wird die Datenlänge gegen die konfigurierten Bitlängen über den Guard <code>(Length &gt;= Config-&gt;MinDataLength/8) &amp;&amp; (Length &lt;= Config-&gt;MaxDataLength/8)</code> geprüft:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Evaluierung zu <code>[FALSE]</code>: Der Kontrollfluss zweigt nach rechts ab und terminiert im Endknoten <code>wrong input</code> (Rückgabewert <code>E2E_E_INPUTERR_WRONG</code>).</li>\n<li>Evaluierung zu <code>[TRUE]</code>: Der Kontrollfluss führt direkt vertikal in den Endknoten <code>input ok</code>, womit die Eingangsprüfung erfolgreich abgeschlossen ist und die Ausführung von <code>E2E_P06Protect()</code> fortgesetzt werden darf.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00424]</code> ist das in der Abbildung spezifizierte Verhalten normativ verpflichtend für Implementierungen von <code>E2E_P06Protect()</code>.</p>\n<p class=\"fig-p\">Entwickler-Hinweise:</p>\n<ul class=\"fig-list\">\n<li>Beide Bedingungen müssen in exakt dieser Reihenfolge geprüft werden; die Nullzeigerprüfung guardet den dereferenzierenden Zugriff auf <code>Config-&gt;MinDataLength</code> bzw. <code>Config-&gt;MaxDataLength</code>.</li>\n<li>Die Konfigurationsgrenzen <code>MinDataLength</code> und <code>MaxDataLength</code> sind in Bits definiert, weshalb der Vergleich mit <code>Length</code> (in Bytes) durch Division durch 8 (<code>/ 8</code>) normiert werden muss.</li>\n<li>Das Ergebnis <code>no input</code> korrespondiert mit dem Fehlercode <code>E2E_E_INPUTERR_NULL</code>, <code>wrong input</code> mit <code>E2E_E_INPUTERR_WRONG</code> und <code>input ok</code> mit dem regulären Fortsetzen der Schutzfunktionslogik.</li>\n</ul>"}], "trans": [{"from": "FIG-3875df6edc21c257", "to": "FIG-3e360a8db9d01f02", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-3e360a8db9d01f02", "to": "FIG-6a4321c1015804e9", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
